mapper.select:
select * from `collect`

     and user_id = #{userId}
     and goods_id = #{goodsId}

order by id desc

mapper.update:
update `collect` set user_id = #{userId}, goods_id = #{goodsId},
    goods_name = #{goodsName}, goods_img = #{goodsImg}, goods_price = #{goodsPrice}, `time` = #{time}
where id = #{id}
